{
  "technical_and_design_decisions": [
    "Preserve existing Spring XD/Spring Cloud Stream configuration and REST compatibility wherever possible, adding optional fields and endpoints rather than changing existing contracts.",
    "Model multiple external systems of the same binding type as uniquely named connection instances, with explicit source and target selection in the module or binding configuration.",
    "Use Hadoop HA-aware filesystem and proxy creation APIs based on the configured logical nameservice, avoiding the existing non-HA NameNode proxy path.",
    "Move the Cassandra and analytic-PMML modules with their existing behavior and metadata, adapting package names, build configuration, dependency versions, module descriptors, and repository integration as required.",
    "Represent job composition with a stable job identifier, parent-child relationships, composition metadata, and a graph DTO suitable for REST and UI consumption.",
    "Expose separate REST responses for the composition flag and the composition graph, while retaining the existing single-job detail behavior.",
    "Implement UI differentiation using composition metadata and graph relationships, and route both standalone jobs and composed-job entities to the appropriate job detail page.",
    "Use automated unit, integration, REST, module, and UI tests for the new behavior; use existing project conventions and test frameworks rather than introducing new tooling."
  ],
  "assumptions": [
    "The increment targets an existing Spring XD/Spring Cloud Stream codebase with buildable backend and frontend repositories and an established CI test environment.",
    "The referenced XD and spring-xd-ambari code, issue details, and existing module implementations are available locally or through the project repositories.",
    "U1 requires simultaneous configuration and use of multiple external systems for one binding type, but does not require a new provider abstraction or support for arbitrary protocols beyond those already supported.",
    "U2 requires support for Hadoop NameNode HA configuration for custom HDFS module locations, including validation against a representative HA configuration; it does not require changes to Hadoop itself.",
    "U3 and U4 are repository/module migrations and compatibility adaptations, not redesigns of Cassandra or PMML processing semantics.",
    "The existing job model already contains enough information to determine parent-child composition, or can be extended without a data migration.",
    "The REST API can expose JSON DTOs and does not require authentication, authorization, pagination, or versioned API infrastructure changes beyond existing conventions.",
    "The UI already has job list and job detail views, routing, styling, and a test framework that can be extended.",
    "Work includes implementation, code review preparation, automated tests, local debugging, integration verification, documentation, and reasonable defect correction, but excludes infrastructure procurement, major dependency upgrades, and release management outside the repositories.",
    "Estimates are for one developer's work-hours and represent most-likely effort, not elapsed calendar time."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Repository discovery and implementation baseline",
      "activity_description": "Inspect the XD/SCS backend, frontend, module repositories, build conventions, existing binding abstractions, HDFS location handling, job APIs, UI routes, and test infrastructure. Identify affected components and establish a buildable baseline.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Cross-cutting design and API specification",
      "activity_description": "Define configuration models for multiple same-type external systems, HA filesystem resolution behavior, module migration boundaries, job composition DTOs and endpoint contracts, UI state mapping, compatibility behavior, and test scenarios.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A3",
      "activity_name": "Multiple external systems for one binding type",
      "activity_description": "Implement named connection or binding-instance configuration, selection and resolution logic, lifecycle handling, validation, backward-compatible defaults, and the changes needed to read from one external system and write to another.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "A4",
      "activity_name": "Tests for multiple external system support",
      "activity_description": "Add unit and integration coverage for multiple instances of the same binding type, source-to-target routing, configuration validation, backward compatibility, error handling, and lifecycle behavior.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A5",
      "activity_name": "HDFS NameNode HA support for custom module locations",
      "activity_description": "Trace custom module location resolution, consume the configured logical HA nameservice, select the HA-aware Hadoop filesystem/proxy APIs, preserve non-HA behavior, and update configuration/error handling.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A6",
      "activity_name": "HDFS HA verification and regression testing",
      "activity_description": "Add tests using mocked or embedded Hadoop configuration for HA and non-HA deployments, validate custom module lookup behavior, and verify compatibility with existing Ambari-related configuration.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A7",
      "activity_name": "Cassandra module migration",
      "activity_description": "Move the Cassandra module into the SCS repository, adapt package and build metadata, dependencies, module descriptors, configuration, documentation, and registration, and ensure it remains usable as a streaming sink.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A8",
      "activity_name": "Cassandra module testing",
      "activity_description": "Port and update existing tests, add sink contract and configuration coverage, verify serialization and connection behavior, and perform a representative module integration test.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A9",
      "activity_name": "Analytic-PMML module migration",
      "activity_description": "Move the analytic-PMML module into the SCS repository, adapt source structure, build metadata, dependencies, module descriptors, configuration, documentation, and processor registration.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "A10",
      "activity_name": "Analytic-PMML module testing",
      "activity_description": "Port and update module tests, verify PMML loading and evaluation, validate processor input/output contracts, and perform compatibility testing with representative streaming data.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A11",
      "activity_name": "Job composition backend model and flag endpoint",
      "activity_description": "Add or expose composition metadata in the backend job model and implement the REST endpoint returning whether a job is standalone or part of a composed workflow, including validation and compatibility behavior.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A12",
      "activity_name": "Job composition graph endpoint",
      "activity_description": "Implement graph extraction for parent-child job relationships, define node and edge DTOs, handle roots, children, missing or terminal entities, cycles or invalid data, and expose the graph through the REST API.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "A13",
      "activity_name": "Backend REST and composition testing",
      "activity_description": "Add controller, service, serialization, authorization-through-existing-mechanisms, standalone-job, composed-job, nested relationship, and error-case tests for both composition endpoints.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A14",
      "activity_name": "UI composition visualization differentiation",
      "activity_description": "Consume composition metadata, update job list and related views to visually distinguish composed workflows from standalone jobs, and add the required labels, icons, styling, and state handling.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A15",
      "activity_name": "UI job detail navigation",
      "activity_description": "Implement routing and click behavior so standalone jobs, parent jobs, child jobs, and graph entities navigate to the correct job detail page while preserving existing navigation and loading/error behavior.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A16",
      "activity_name": "Frontend automated tests",
      "activity_description": "Add or update component, service, routing, and interaction tests for visual differentiation, composition graph data handling, and navigation for both singular and composed-job entities.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A17",
      "activity_name": "End-to-end integration and compatibility verification",
      "activity_description": "Build all affected repositories, run the complete automated test suites, exercise representative stream and job-composition scenarios, verify module discovery and HDFS behavior, and resolve cross-component integration issues.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A18",
      "activity_name": "Documentation and delivery preparation",
      "activity_description": "Update configuration reference, REST endpoint documentation, module usage examples, migration notes, release notes, and repository build or deployment instructions; prepare the changes for review.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A19",
      "activity_name": "Defect correction and final regression pass",
      "activity_description": "Address defects found during implementation and integration, perform targeted regression testing across all eight user stories, clean up code and diagnostics, and verify the final increment against acceptance scenarios.",
      "most_likely_effort": 32
    }
  ],
  "reported_total": {
    "most_likely_effort": 632
  }
}

